            srealizes SEGS scfg (mkCfg (mkst (regupd R 10 a) (v_addi (Z_to_bv 64 (pc cs)) 4) FULL' (seg_rom SEGS)) model') TB).
  { intros a model' FULL' Hg GPo GM Hfs.
    destruct (mmap_null_cs1 cs kd eager ne nlo nhi E R FULL model a model' FULL' HC HML Hfresh Hnev HbudI Hkind Hkfog Hnoh Hg GPo GM)
      as (HC1 & Hbase & HneE' & Un & Hag0 & Hag & Hv & (Hal & H4096 & HaT & HT & Hnlh & HnZpos & _ & Hvlo & Hvhi) & Hapart & NEW).
    fold len nZ n in HC1, HneE', Un, HaT, Hnlh, HnZpos, Hvlo, Hvhi, Hapart, NEW.
    rewrite (v_addi_pc (pc cs) Hp0 Hp4). rewrite bv5_10.
    set (E' := ext1 E (nxt cs) (Z_to_bv 64 (bv_unsigned a / 4096))) in *.
    (* [comment removed for export] *)
    set (cs1 := null_cs1 A rz cs kd eager ne nlo nhi) in *.
    pose proof (u64_range a) as Ra.
    (* [comment removed for export] *)
    assert (FINOK : forall c0 c, CSOK E' c0 (regupd R (Z_to_bv 5 (Z.of_nat 10)) a) FULL' model' ->
              kimg_in_hull A (kn c0) -> pc c0 = pc cs + 4 ->
              (if visible then vis_add A LIMIT c0 (null_base cs) ne ([KWr (SA (null_base cs) 0) ne; KZero (SA (null_base cs) 0) ne] ++ kn c0) else Some c0) = Some c ->
              CSOK E' c (regupd R (Z_to_bv 5 (Z.of_nat 10)) a) FULL' model' /\ pc c = pc cs + 4).
    { intros c0 c HC0 Hkh Hpc0 Hfin. destruct visible.
      - split; [| destruct (vis_add_inv _ _ _ _ _ Hfin) as (nhi2 & _ & ->); exact Hpc0].
        assert (Hrw : kind_none kd = false) by (destruct kd; cbn in Hvisible |- *; congruence).
        eapply (grant_vis_add E' c0 c _ ne _ FULL' model' a n nZ HC0 Hfin Hkh Hbase HneE' Un); [lia | unfold TOPC in *; lia | |].
        + intros x Hx. destruct (NEW x Hx) as (N1 & N2 & N3 & _). rewrite (gp_noacc _ _ _ _ _ GPo), Hrw. auto.
        + intros x Hx. rewrite (proj2 GM x) by (rewrite Un; exact Hx). rewrite Hrw. reflexivity.
      - injection Hfin as <-. split; [exact HC0 | exact Hpc0]. }
    assert (KH1 : kimg_in_hull A (kn cs1)).
    { unfold cs1, null_cs1, add_entry. cbn [kn a_ss mk_ss s_know]. apply kimg_in_hull_app; [|apply kimg_clip_in_hull'].
      apply kimg_in_hull_pure. apply null_kfacts_pure. }
    assert (KH2 : forall e lo hi, kimg_in_hull A (kn (set_kn cs1 (KRange e lo hi :: kn cs1)))).
    { intros e lo hi. change (kn (set_kn cs1 (KRange e lo hi :: kn cs1))) with (KRange e lo hi :: kn cs1).
      apply (kimg_in_hull_app A [KRange e lo hi]); [apply kimg_in_hull_pure; repeat constructor | exact KH1]. }
    assert (PC1 : pc cs1 = pc cs + 4) by reflexivity.
    assert (PC2 : forall K, pc (set_kn cs1 (K :: kn cs1)) = pc cs + 4) by (intros; exact PC1).
    (* [comment removed for export] *)
    assert (USEA : forall c, CSOK E' c (regupd R (Z_to_bv 5 (Z.of_nat 10)) a) FULL' model' -> pc c = pc cs + 4 -> c = csa ->
              srealizes SEGS scfg (mkCfg (mkst (regupd R (Z_to_bv 5 (Z.of_nat 10)) a) (Z_to_bv 64 (pc cs + 4)) FULL' (seg_rom SEGS)) model') TB).
    { intros c HCc Hpcc ->. specialize (HKA E' (regupd R (Z_to_bv 5 (Z.of_nat 10)) a) FULL' model' (conj Hag0 Hag) HCc Hfs).
      unfold cfg_of in HKA. rewrite Hpcc in HKA. exact HKA. }
    assert (USEB : forall c, CSOK E' c (regupd R (Z_to_bv 5 (Z.of_nat 10)) a) FULL' model' -> pc c = pc cs + 4 -> c = csb ->
              srealizes SEGS scfg (mkCfg (mkst (regupd R (Z_to_bv 5 (Z.of_nat 10)) a) (Z_to_bv 64 (pc cs + 4)) FULL' (seg_rom SEGS)) model') TB).
    { intros c HCc Hpcc ->. specialize (HKB E' (regupd R (Z_to_bv 5 (Z.of_nat 10)) a) FULL' model' (conj Hag0 Hag) HCc Hfs).
      unfold cfg_of in HKB. rewrite Hpcc in HKB. exact HKB. }
    (* [comment removed for export] *)
    assert (SINGLE : match (if visible then vis_add A LIMIT cs1 (null_base cs) ne ([KWr (SA (null_base cs) 0) ne; KZero (SA (null_base cs) 0) ne] ++ kn cs1) else Some cs1)
                     with Some c => Some (contra_cs c, c) | None => None end = Some (csa, csb) ->
              srealizes SEGS scfg (mkCfg (mkst (regupd R (Z_to_bv 5 (Z.of_nat 10)) a) (Z_to_bv 64 (pc cs + 4)) FULL' (seg_rom SEGS)) model') TB).
    { intros Hs. match type of Hs with (match ?f with Some _ => _ | None => None end) = _ => destruct f as [c|] eqn:Hfin; [|discriminate] end.
      injection Hs as _ ->. destruct (FINOK cs1 csb HC1 KH1 PC1 Hfin) as [HCc Hpcc]. exact (USEB csb HCc Hpcc eq_refl). }
    cbv zeta in Hn. fold cs1 in Hn.
    destruct (negb (split && visible)); [exact (SINGLE Hn)|].
    destruct (first_run (a_maps cs)) as [[flo fhi]|] eqn:Hfr; [|exact (SINGLE Hn)].
    pose proof (null_first_run E' (a_maps cs) (bv_unsigned a) nZ flo fhi Hapart HnZpos Hfr) as SIDE.
    match type of Hn with (if ?c then _ else _) = _ => destruct c eqn:Hdec; [exact (SINGLE Hn)|] end.
    destruct (Z.ltb (null_vhi nlo) (zcdiv' fhi 4096)) eqn:Hlt.
    - (* [comment removed for export] *)
      apply Z.ltb_lt in Hlt.
      assert (LOW : bv_unsigned a + nZ <= flo).
      { destruct SIDE as [LOW|HIGH]; [exact LOW|]. exfalso. pose proof (null_high_vbot (bv_unsigned a) fhi HIGH Hal). lia. }
      match type of Hn with (match ?f with Some _ => _ | None => None end) = _ => destruct f as [c|] eqn:Hfin; [|discriminate] end.
      injection Hn as _ ->.
      destruct (FINOK _ csb (null_child_ok E' cs1 _ FULL' model' _ HC1 (fun M => null_low_fact E' (nxt cs) a nZ nlo flo (null_vlo A cs nlo) M Hv Hvlo LOW ltac:(lia)))
                  (KH2 _ _ _) (PC2 _) Hfin) as [HCc Hpcc].
      exact (USEB csb HCc Hpcc eq_refl).
    - (* [comment removed for export] *)
      match type of Hn with (match ?f with Some _ => _ | None => _ end) = _ => destruct f as [cL|] eqn:HfinL; [|discriminate] end.
      match type of Hn with (match ?f with Some _ => _ | None => None end) = _ => destruct f as [cH|] eqn:HfinH; [|discriminate] end.
      injection Hn as -> ->.
      destruct SIDE as [LOW|HIGH].
      + destruct (FINOK _ csa (null_child_ok E' cs1 _ FULL' model' _ HC1 (fun M => null_low_fact E' (nxt cs) a nZ nlo flo (null_vlo A cs nlo) M Hv Hvlo LOW ltac:(lia)))
                    (KH2 _ _ _) (PC2 _) HfinL) as [HCc Hpcc].
        exact (USEA csa HCc Hpcc eq_refl).
      + destruct (FINOK _ csb (null_child_ok E' cs1 _ FULL' model' _ HC1 (fun M => null_high_fact E' (nxt cs) a fhi (null_vhi nlo) M Hv Hvhi HIGH Hal))
                    (KH2 _ _ _) (PC2 _) HfinH) as [HCc Hpcc].
        exact (USEB csb HCc Hpcc eq_refl). }
  (* [comment removed for export] *)
  unfold cfg_of.
  destruct kd; cbn [kind_none kind_lazy negb orb] in *; [| | | | discriminate Hkfog | discriminate Hkfog].
  - (* [comment removed for export] *)
    destruct eager; [|discriminate].
    (* [comment removed for export] *)
