Lemma mmap_gate_sound : forall cs prot flags isnull,
  mmap_gate cs = Some (prot, flags, isnull) ->
  reg_lit cs 17 = Some 222 /\ reg_lit cs 12 = Some prot /\ reg_lit cs 13 = Some flags
  /\ reg_lit cs 14 = Some (two64 - 1) /\ reg_lit cs 15 = Some 0
  /\ (isnull = true -> reg_lit cs 10 = Some 0).
Proof.
  intros cs prot flags isnull Hg. unfold mmap_gate in Hg.
  destruct (reg_lit cs 17) as [z17|] eqn:H17; [|discriminate].
  destruct (reg_lit cs 12) as [p|] eqn:H12.
  2: { repeat match type of Hg with context [match ?x with _ => _ end] => destruct x; try discriminate end. }
  destruct (reg_lit cs 13) as [f|] eqn:H13.
  2: { repeat match type of Hg with context [match ?x with _ => _ end] => destruct x; try discriminate end. }
  destruct (reg_lit cs 14) as [m1|] eqn:H14.
  2: { repeat match type of Hg with context [match ?x with _ => _ end] => destruct x; try discriminate end. }
  destruct (reg_lit cs 15) as [z15|] eqn:H15.
  2: { repeat match type of Hg with context [match ?x with _ => _ end] => destruct x; try discriminate end. }
  assert (Hz : z17 = 222 /\ z15 = 0).
  { repeat match type of Hg with context [match ?x with _ => _ end] => destruct x; try discriminate end; auto. }
  destruct Hz as [-> ->]. cbn iota in Hg.
  match type of Hg with (if negb ?c then None else _) = _ => destruct c eqn:Hm1; [|discriminate] end. cbn [negb] in Hg.
  apply Z.eqb_eq in Hm1. subst m1. injection Hg as <- <- <-.
  repeat split; try reflexivity.
  destruct (reg_lit cs 10) as [[|p10|p10]|]; intros H; try discriminate H. reflexivity.
Qed.

Theorem node_mmap2_sound : forall split : bool, mm2_stmt SEGS scfg A nx0 LIMIT SINV argH FS0 (node_mmap2 A nx0 LIMIT rz split).
Proof.
  intros split cs csa csb E R FULL model TB HC Hec Hn HKA HKB.
  unfold node_mmap2 in Hn.
  destruct (mmap_gate cs) as [[[prot flags] isnull]|] eqn:Hg; [|discriminate].
  destruct (mmap_gate_sound cs prot flags isnull Hg) as (H17 & H12 & H13 & H14 & H15 & H10).
  match type of Hn with (match ?g with Some p => Some p | None => None end) = _ => destruct g as [pr|] eqn:HG; [|discriminate] end.
  injection Hn as ->.
  destruct isnull.
  - specialize (H10 eq_refl).
    assert (ARMS : (prot = 3 /\ flags = 34 /\ mmap_null A nx0 LIMIT rz split cs KRW true true = Some (csa, csb))
                   \/ (prot = 3 /\ flags = 16418 /\ mmap_null A nx0 LIMIT rz split cs KRWLAZY false true = Some (csa, csb))
                   \/ (prot = 0 /\ flags = 34 /\ mmap_null A nx0 LIMIT rz split cs KNONE false false = Some (csa, csb))
                   \/ (prot = 0 /\ flags = 16418 /\ mmap_null A nx0 LIMIT rz split cs KNONELAZY false false = Some (csa, csb))).
    { repeat match type of HG with context [match ?x with _ => _ end] => destruct x; try discriminate end; tauto. }
    destruct ARMS as [(-> & -> & Hm)|[(-> & -> & Hm)|[(-> & -> & Hm)|(-> & -> & Hm)]]].
    + eapply (mmap_null_sound2 split cs KRW true true); eauto; reflexivity.
    + eapply (mmap_null_sound2 split cs KRWLAZY false true); eauto; reflexivity.
    + eapply (mmap_null_sound2 split cs KNONE false false); eauto; reflexivity.
    + eapply (mmap_null_sound2 split cs KNONELAZY false false); eauto; reflexivity.
  - (* [comment removed for export] *)
    assert (ARMS : (prot = 3 /\ flags = 16434 /\ mmap_fixed_free A LIMIT cs KRWLAZY false false = Some (csa, csb))
                   \/ (prot = 3 /\ flags = 50 /\ mmap_fixed_free A LIMIT cs KRW true true = Some (csa, csb))
                   \/ (prot = 0 /\ flags = 16434 /\ mmap_fixed_free A LIMIT cs KNONELAZY false false = Some (csa, csb))
                   \/ (prot = 0 /\ flags = 50 /\ mmap_fixed_free A LIMIT cs KNONE false false = Some (csa, csb))
                   \/ (prot = 3 /\ (flags = 1064994 \/ flags = 1065010) /\ mmap_fixed_free A LIMIT cs KRWLAZY false false = Some (csa, csb))
                   \/ (prot = 0 /\ (flags = 1064994 \/ flags = 1065010) /\ mmap_fixed_free A LIMIT cs KNONELAZY false false = Some (csa, csb))).
    { repeat match type of HG with context [match ?x with _ => _ end] => destruct x; try discriminate end; tauto. }
    destruct ARMS as [(-> & -> & Hm)|[(-> & -> & Hm)|[(-> & -> & Hm)|[(-> & -> & Hm)|[(-> & [->| ->] & Hm)|(-> & [->| ->] & Hm)]]]]].
    + eapply (mmap_fixed_free_sound2 cs KRWLAZY false false 16434 csa csb); eauto; try reflexivity;
        try (unfold two64; lia); try apply AsanNodesMmLibK.fixed_free_core_4032; try apply mmap_noreserve_b_4032.
    + eapply (mmap_fixed_free_sound2 cs KRW true true 50 csa csb); eauto; try reflexivity;
        try (unfold two64; lia); try apply AsanNodesMmLibK.fixed_free_core_32; try apply mmap_noreserve_b_32.
    + eapply (mmap_fixed_free_sound2 cs KNONELAZY false false 16434 csa csb); eauto; try reflexivity;
        try (unfold two64; lia); try apply AsanNodesMmLibK.fixed_free_core_4032; try apply mmap_noreserve_b_4032.
    + eapply (mmap_fixed_free_sound2 cs KNONE false false 50 csa csb); eauto; try reflexivity;
        try (unfold two64; lia); try apply AsanNodesMmLibK.fixed_free_core_32; try apply mmap_noreserve_b_32.
    + eapply (mmap_fixed_free_sound2 cs KRWLAZY false false 1064994 csa csb); eauto; try reflexivity;
        try (unfold two64; lia); try apply AsanNodesMmLibK.fixed_free_core_104022; try apply mmap_noreserve_b_104022.
    + eapply (mmap_fixed_free_sound2 cs KRWLAZY false false 1065010 csa csb); eauto; try reflexivity;
        try (unfold two64; lia); try apply AsanNodesMmLibK.fixed_free_core_104032; try apply mmap_noreserve_b_104032.
    + eapply (mmap_fixed_free_sound2 cs KNONELAZY false false 1064994 csa csb); eauto; try reflexivity;
        try (unfold two64; lia); try apply AsanNodesMmLibK.fixed_free_core_104022; try apply mmap_noreserve_b_104022.
    + eapply (mmap_fixed_free_sound2 cs KNONELAZY false false 1065010 csa csb); eauto; try reflexivity;
        try (unfold two64; lia); try apply AsanNodesMmLibK.fixed_free_core_104032; try apply mmap_noreserve_b_104032.
