Lemma reserved_free_above : forall model (lo n : word),
  (exists rx : list (word * word),
     vm_reserved (m_vmmaps model) = segments_reserved SEGS ++ rx
     /\ Forall (resx_entry_ok A) rx
     /\ (length rx <= n_resx A)%nat
     /\ sum_sizes rx <= resx_bytes A) ->
